// Clean input (Code node, run once for all items).
// Turns the raw form payload into the values every later step relies on.
// Every rule below exists because of something in the sample data.
const body = $input.first().json.body || {};

const str = (v) => (v == null ? '' : String(v));
const squash = (s) => str(s).replace(/\s+/g, ' ').trim();

// Email: "John@Example.com " and "john@example.com" are the same person.
const email = str(body.email).trim().toLowerCase();
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  throw new Error(`Invalid email reached n8n: "${email}"`);
}

// Interests: the sample has "Api" and "API" for the same thing, and
// people type commas, semicolons, slashes or new lines.
const CANON = { api: 'API', apis: 'API', doc: 'Docs', docs: 'Docs', documentation: 'Docs',
  support: 'Support', training: 'Training', trainings: 'Training' };
const titleCase = (s) => s.toLowerCase().replace(/\b\p{L}/gu, (c) => c.toUpperCase());
const seen = new Set();
const interests = [];
for (const raw of str(body.interests).split(/[,;\/|\n]+/)) {
  const cleaned = squash(raw).replace(/^[-*•]\s*/, '').slice(0, 50);
  if (!cleaned) continue;
  const key = cleaned.toLowerCase();
  const name = CANON[key] || titleCase(cleaned);
  if (seen.has(name.toLowerCase())) continue;
  seen.add(name.toLowerCase());
  interests.push(name);
  if (interests.length >= 20) break;
}

// Urgent: the sample writes "urgent:" and "urgent -", so match the word,
// any case, any punctuation. "Not urgent" is a real thing people write,
// and sending them the urgent email would be wrong, so it counts as welcome.
const comment = str(body.comment).trim().slice(0, 2000);
const mentionsUrgent = /\burgent(ly)?\b/i.test(comment);
const negated = /\b(not|isn'?t|no|non)[\s-]+(that\s+|very\s+|super\s+)?urgent/i.test(comment);
const type = mentionsUrgent && !negated ? 'urgent' : 'welcome';

const utm = squash(body.utm_source).toLowerCase().slice(0, 100) || 'direct';

return [{
  json: {
    request_id: str(body.request_id),
    full_name: squash(body.full_name).slice(0, 120),
    email,
    email_raw: str(body.email).slice(0, 254),
    comment,
    interests_raw: str(body.interests).slice(0, 1000),
    interests,
    interests_count: interests.length,
    utm_source: utm,
    type,
    urgent_reason: mentionsUrgent ? (negated ? 'says not urgent' : 'contains "urgent"') : 'no "urgent" in comment',
    is_test: body.is_test === true,
  },
}];

// Build email (Code node, run once for all items).
// The brief says the two templates are in the spreadsheet. They aren't,
// so these are mine. Plain, short, and they say what happens next.
const lead = $('Clean input').first().json;
const first = (lead.full_name.split(' ')[0] || 'there').replace(/[<>&"]/g, '');
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const NEXT = {
  API: 'API reference and keys: we will send setup steps for your account.',
  Docs: 'Docs: start with the quick-start guide, it takes about 10 minutes.',
  Support: 'Support: reply to this email any time and it reaches a person.',
  Training: 'Training: we run live onboarding sessions every week, we will send dates.',
};
const lines = lead.interests.map((i) => NEXT[i] || `${i}: we will follow up with what we have on this.`);

let subject, text;
if (lead.type === 'urgent') {
  subject = 'We got your urgent request';
  text = [
    `Hi ${first},`,
    '',
    'Thanks for reaching out. Your message is marked urgent, so a person on our team will contact you within 1 business hour.',
    '',
    'What you wrote:',
    `"${lead.comment}"`,
    '',
    'If anything changes before then, just reply to this email.',
    '',
    'The Team',
  ].join('\n');
} else {
  subject = `Welcome, ${first}`;
  text = [
    `Hi ${first},`,
    '',
    'Thanks for getting in touch. Here is what happens next:',
    '',
    ...(lines.length ? lines.map((l) => `- ${l}`) : ['- We will reply to your message within 1 business day.']),
    '',
    'Questions in the meantime? Reply here.',
    '',
    'The Team',
  ].join('\n');
}

// Sandbox: test submissions and example.com addresses never reach a real
// inbox. They go to the sandbox address with the real recipient in the subject.
const sandbox = lead.is_test || /@(example\.(com|org|net)|test\.invalid)$/i.test(lead.email);
const to = sandbox ? $env.LEADCASE_SANDBOX_EMAIL : lead.email;
if (sandbox) subject = `[SANDBOX to ${lead.email}] ${subject}`;

const html = `<div style="font-family:Arial,sans-serif;font-size:15px;line-height:1.5;color:#14171f">${
  esc(text).split('\n').map((l) => (l ? `<p style="margin:0 0 4px">${l}</p>` : '<br>')).join('')
}</div>`;

return [{ json: { to, subject, text, html, sandbox, type: lead.type } }];

// Describe failure (Code node, run once for all items).
// Any step's error output lands here. Turn whatever shape the error has into
// three plain values so "Mark failed" can always record it.
const item = $input.first().json || {};
const err = item.error;
const message = String(
  item.message || (err && (err.message || err.description)) || err || 'unknown error'
).slice(0, 500);

let leadId = 0;
try { leadId = Number($('Add to Leads').first().json.lead_id) || 0; } catch (e) { /* failed before the lead was saved */ }
let email = '';
try { email = $('Clean input').first().json.email || ''; } catch (e) { /* failed before cleaning */ }

let failedStep = 'unknown';
try { failedStep = (err && err.node && err.node.name) || 'unknown'; } catch (e) {}

return [{ json: { lead_id: leadId, email, note: `${failedStep}: ${message}` } }];
